args.content:
/* Halcyon Threshold - Clean, thoughtful design */

:root {
    --primary: #2c5282;
    --primary-light: #4a90c2;
    --text: #2d3748;
    --text-light: #718096;
    --background: #ffffff;
    --background-alt: #f7fafc;
    --accent: #48bb78;
    --border: #e2e8f0;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    line-height: 1.7;
    color: var(--text);
    background: var(--background);
}

/* Navigation */
header {
    border-bottom: 1px solid var(--border);
    padding: 1rem 2rem;
}

nav {
    max-width: 1000px;
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--primary);
    text-decoration: none;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a {
    color: var(--text);
    text-decoration: none;
    font-size: 0.95rem;
}

.nav-links a:hover {
    color: var(--primary);
}

/* Main content */
main {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

section {
    margin-bottom: 4rem;
}

/* Hero */
.hero {
    text-align: center;
    padding: 4rem 0;
}

.hero h1 {
    font-size: 2.5rem;
    font-weight: 600;
    color: var(--primary);
    margin-bottom: 1rem;
    line-height: 1.2;
}

.tagline {
    font-size: 1.25rem;
    color: var(--text-light);
    max-width: 600px;
    margin: 0 auto;
}

/* Sections */
h2 {
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--primary);
    margin-bottom: 1.5rem;
}

h3 {
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text);
    margin-bottom: 0.5rem;
}

p {
    margin-bottom: 1rem;
}

a {
    color: var(--primary-light);
}

/* Pillars grid */
.pillar-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 2rem;
}

.pillar {
    padding: 1.5rem;
    background: var(--background-alt);
    border-radius: 8px;
}

/* CTA */
.cta {
    background: var(--background-alt);
    padding: 2rem;
    border-radius: 8px;
    text-align: center;
}

/* Footer */
footer {
    border-top: 1px solid var(--border);
    padding: 2rem;
    text-align: center;
    color: var(--text-light);
    font-size: 0.9rem;
}

.small {
    font-size: 0.8rem;
    margin-top: 0.5rem;
}

/* Resource list */
.resource-list {
    list-style: none;
}

.resource-list li {
    padding: 1rem 0;
    border-bottom: 1px solid var(--border);
}

.resource-list li:last-child {
    border-bottom: none;
}

.resource-category {
    font-size: 0.85rem;
    color: var(--text-light);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.25rem;
}

/* Responsive */
@media (max-width: 600px) {
    .hero h1 {
        font-size: 1.8rem;
    }

    header {
        padding: 1rem;
    }

    .nav-links {
        gap: 1rem;
    }
}
